SELECT '==ANY LOGS REFERENCING ASSIGNID 255 OR 256 FOR USER 2558==' as '';
SELECT id, eventname, userid AS actor, relateduserid, contextinstanceid, from_unixtime(timecreated) AS dt, other FROM isi_logstore_standard_log WHERE relateduserid = 2558 AND other LIKE '%255%' OR (relateduserid = 2558 AND other LIKE '%256%') ORDER BY timecreated;
SELECT '==ANY LOGS BY USER 2558 WITH ASSIGNID IN other==' as '';
SELECT id, eventname, userid, relateduserid, from_unixtime(timecreated) AS dt, other FROM isi_logstore_standard_log WHERE userid = 2558 AND (other LIKE '%"assignid":"255"%' OR other LIKE '%"assignid":"256"%') ORDER BY timecreated;
SELECT '==ANY LOGS ABOUT USER 2558 SUBMISSION VIEW OR GRADE==' as '';
SELECT id, eventname, userid, relateduserid, contextinstanceid, from_unixtime(timecreated) AS dt, other FROM isi_logstore_standard_log WHERE relateduserid = 2558 AND eventname LIKE '%submission%' ORDER BY timecreated DESC LIMIT 20;
SELECT '==WHEN WAS ASSIGN 255 / 256 CREATED OR LAST MODIFIED==' as '';
SELECT id, course, name, duedate, grade, timecreated, timemodified, allowsubmissionsfromdate, cutoffdate FROM isi_assign WHERE id IN (255, 256);
SELECT '==CHECK IF SUBMISSION WAS RE-EDITED LATER==' as '';
SELECT id, assignment, userid, from_unixtime(timecreated) tc, from_unixtime(timemodified) tm, status, groupid, attemptnumber, latest FROM isi_assign_submission WHERE assignment IN (255, 256) AND userid = 2558;